const fs = require("fs");
const repoSkills = fs.readdirSync("./skills").filter(f => fs.statSync(`./skills/${f}`).isDirectory() && fs.existsSync(`./skills/${f}/SKILL.md`));
console.log("Total skills in ECC repo:", repoSkills.length);

const installedSkillsDir = "/Users/ctp-itdev2/.config/opencode/skills";
const installedSkills = fs.readdirSync(installedSkillsDir).filter(f => {
  const p = `${installedSkillsDir}/${f}`;
  try { return (fs.statSync(p).isDirectory() || fs.lstatSync(p).isSymbolicLink()) && fs.existsSync(`${p}/SKILL.md`); } catch { return false; }
});
console.log("Total skills in ~/.config/opencode/skills:", installedSkills.length);

// How many of repoSkills are in installedSkills?
const eccInstalled = repoSkills.filter(s => installedSkills.includes(s));
console.log("ECC repo skills currently installed in OpenCode:", eccInstalled.length, "out of", repoSkills.length, `(${Math.round(eccInstalled.length/repoSkills.length*100)}%)`);

// Skills by module
const installModules = JSON.parse(fs.readFileSync("./manifests/install-modules.json", "utf8"));
const allMods = Array.isArray(installModules) ? installModules : installModules.modules || Object.values(installModules);
const skillsByModule = {};
for (const m of allMods) {
  const modSkills = (m.paths || []).filter(p => p.startsWith("skills/")).map(p => p.replace("skills/", ""));
  if (modSkills.length > 0) {
    const installed = modSkills.filter(s => installedSkills.includes(s));
    skillsByModule[m.id] = { total: modSkills.length, installed: installed.length, targets: m.targets };
  }
}
console.log("\nSkill coverage by module:");
for (const [modId, info] of Object.entries(skillsByModule)) {
  const pct = Math.round(info.installed / info.total * 100);
  const status = info.installed === info.total ? "FULL" : (info.installed > 0 ? "PARTIAL" : "NONE");
  console.log(`- ${modId.padEnd(30)} ${String(info.installed).padStart(3)} / ${String(info.total).padStart(3)} (${String(pct).padStart(3)}%) [${status}] opencode-supported: ${(info.targets||[]).includes("opencode")}`);
}
'

