// Test countUserTurns logic
function countUserTurns(messages) {
  let totalUserTurns = 0;
  let turnsSinceLastCompress = 0;
  let foundLastCompress = false;
  for (let i = messages.length - 1; i >= 0; i--) {
    const msg = messages[i];
    const role = msg?.info?.role;
    if (role === "assistant" && !foundLastCompress) {
      const hasCompress = msg.parts?.some(
        (p) => p.type === "tool" && p.tool === "compress" && p.state?.status === "completed"
      );
      if (hasCompress) foundLastCompress = true;
    }
    if (role === "user") {
      const isInternal = msg.parts?.some(
        (p) => typeof p.text === "string" && (p.text.startsWith("/dcp") || p.text.startsWith("<compress triggered manually>"))
      );
      if (!isInternal) {
        totalUserTurns++;
        if (!foundLastCompress) turnsSinceLastCompress++;
      }
    }
  }
  return { totalUserTurns, turnsSinceLastCompress };
}

// Case: 3 user prompts
const msgs3 = [
  { info: { role: "user" }, parts: [{ text: "hi 1" }] },
  { info: { role: "assistant" }, parts: [{ text: "ans 1" }] },
